"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["12403"],{94675(e){e.exports=JSON.parse('{"id":"V4-070","slug":"golden-parachute","term":"Golden Parachute","also_known_as":[],"difficulty":"Intermediate","definition":"A golden parachute is a large payment or package of benefits promised to a senior executive if they lose their job, especially as a result of a takeover or change of control of the company.","explanation":["Golden parachutes can include cash severance, accelerated vesting of shares and options, continued bonuses, pension enhancements and other benefits. They are written into executives\u2019 employment contracts.","Supporters argue they help companies attract executives and encourage them to consider takeover offers objectively, even if accepting would cost them their jobs. Without such protection, executives might resist offers that are good for shareholders.","For example, a chief executive\u2019s contract might entitle them to three times their annual salary and bonus, plus immediate vesting of all share awards, if they are dismissed within two years of the company being acquired.","Critics argue golden parachutes reward executives regardless of performance, can be excessively generous and may make takeovers more expensive. In the United States, shareholders of companies being acquired have an advisory vote on golden parachute payments, and tax rules penalise excessive payments. In the United Kingdom and some other countries, governance codes and shareholder pressure have limited their size."],"note":"","total":1725,"prev":{"slug":"gold-standard","term":"Gold Standard"},"next":{"slug":"goods-and-services-tax","term":"Goods and Services Tax (GST)"}}')}}]);